code.cpp:
class Solution {
public:
    int maxSum(vector<int>& nums) {
        int top1[10] = {0}, top2[10] = {0};
        for (int x : nums) {
            int d = 0, t = x;
            while (t > 0) {
                d = max(d, t % 10);
                t /= 10;
            }
            if (x > top1[d]) {
                top2[d] = top1[d];
                top1[d] = x;
            } else if (x > top2[d]) {
                top2[d] = x;
            }
        }
        int ans = -1;
        for (int d = 1; d <= 9; d++) {
            if (top2[d] > 0) {
                ans = max(ans, top1[d] + top2[d]);
            }
        }
        return ans;
    }
};
